{
  "root_causes": [
    {
      "service": "ts-route-service",
      "fault_kind": "network_loss",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, count(*) n, round(quantile_cont(duration,0.5)/1e6,1) p50_ms, round(quantile_cont(duration,0.95)/1e6,1) p95_ms, round(max(duration)/1e6,1) max_ms FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND span_name LIKE '%routeservice/routes%' GROUP BY span_name",
          "claim": "ts-ui-dashboard GET /api/v1/routeservice/routes: 126 calls all about 3001 ms, versus about 23 ms p95 in normal."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, round(quantile_cont(duration,0.5)/1e6,1) p50_ms FROM abnormal_traces WHERE service_name='ts-route-service' AND span_name='GET /api/v1/routeservice/routes' GROUP BY ALL",
          "claim": "ts-route-service sees only one GET /routes request in the abnormal window; the dashboard's calls never reach it."
        },
        {
          "kind": "log",
          "sql": "SELECT service_name, level, count(*) n FROM abnormal_logs WHERE service_name='ts-ui-dashboard' AND message LIKE '%dial tcp 10.108.144.64:8080: i/o timeout%' AND message LIKE '%routeservice/routes%' GROUP BY ALL",
          "claim": "ts-ui-dashboard proxy logs repeated 'dial tcp ... i/o timeout' with status 502 on /api/v1/routeservice/routes."
        },
        {
          "kind": "metric",
          "sql": "SELECT metric, attr_source, attr_destination, round(avg(value),2) avg_v, max(value) max_v, count(*) n FROM abnormal_metrics_sum WHERE metric='hubble_tcp_flags_total' AND attr_source LIKE '%ui-dashboard%' AND attr_destination LIKE '%route-service%' GROUP BY ALL",
          "claim": "Hubble TCP flag counts ui-dashboard to route-service rose from about 5.6 to about 38 per sample, far beyond the roughly 2x traffic increase."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-route-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, round(quantile_cont(duration,0.5)/1e6,1) p50_ms FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND span_name LIKE '%routeservice/routes%' GROUP BY ALL",
          "claim": "The dashboard's /routes server spans take about 3 s; the route-service dependency is unreachable, so these user requests fail with 502."
        }
      ]
    }
  ]
}
